function canonical(value: unknown): string {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value !== null && typeof value === 'object') {
    const row = value as Record<string, unknown>;
    return '{' + Object.keys(row).sort().map((key) => JSON.stringify(key) + ':' + canonical(row[key])).join(',') + '}';
  }
  return JSON.stringify(value);
}
const hash = (value: unknown) => createHash('sha256').update(canonical(value)).digest('hex');
const owner = 'occurrence:occ-a';
const config = (bundle: AuthoredBundle) => new AuthoredState(bundle).config(owner);
const child = (bundle: AuthoredBundle, id = 'clip-a') => new AuthoredState(bundle).entity(owner + '/clip:' + id)!;
function input(golden: typeof goldens[number]) {
  const bundle = copy(originals[golden.verified.media_type.startsWith('video/') ? 1 : 0]);
  const row = new AuthoredState(bundle).occurrence(owner);
  if (golden.approval.mode === 'shared' || !golden.approval.anchor || golden.approval.anchor === 'gone') row.duration_ms = 20000;
  if (golden.approval.mode === 'shared' || golden.name.endsWith('-preferred') || golden.name.endsWith('-saved')) {
    (config(bundle).tracks as JSON[]).push({ id: 'overlay', kind: 'visual' });
    row.duration_ms = 20000;
  }
  if (golden.approval.mode === 'shared') (config(bundle).clips as JSON[]).push({ id: 'clip-c', track: 'overlay', asset: 'picture', clipType: 'media', at: 1, hold: 8 });
  // JSON parsing models the durable basis, rather than relying on object identity.
  const approval = JSON.parse(JSON.stringify(golden.approval)) as Parameters<typeof captureAutoBasis>[1];
  return { bundle, basis: captureAutoBasis(bundle, approval), media: golden.media, verified: golden.verified };
}

describe('inactive corrected native automatic capture', () => {
  for (const golden of goldens) {
    it('matches native command/record/after parity: ' + golden.name, () => {
      const { bundle, basis, media, verified } = input(golden);
      const before = copy(bundle);
      const result = finishAutoCapture(basis, media, verified);
      expect(result.capture).toEqual(golden.capture);
      const expected = official8130ReadGoldenUpdates[golden.name];
      if (expected) expect([golden.commands, golden.records]).toEqual(expected.old);
      expect(hash(result.commands)).toBe(expected?.next[0] ?? golden.commands);
      expect(hash(result.records)).toBe(expected?.next[1] ?? golden.records);
      expect(hash(result.bundle)).toBe(golden.after);
      expect(bundle).toEqual(before);
      expect(Object.isFrozen(basis.bundle)).toBe(true);
      expect(executeAutoBirth(basis.bundle, result.commands[0], verified).record).toEqual(result.records[0]);
      expect(finishAutoCapture(JSON.parse(JSON.stringify(basis)), media, verified)).toEqual(result);
      expect(result.commands[0].created).toContain(owner + '/clip:placed');
    });
  }
});

const allModes = goldens.filter((golden) => !golden.name.endsWith('-saved'));
const changes: Array<[string, (bundle: AuthoredBundle) => void]> = [
  ['anchor timing', (bundle) => { child(bundle).at = 2; }],
  ['consumed source window', (bundle) => { child(bundle).hold = 2.75; }],
  ['consumed playback speed', (bundle) => { child(bundle).speed = 1.5; }],
  ['clip membership', (bundle) => { (config(bundle).clips as JSON[]).push({ id: 'other', track: 'picture', at: 1, hold: 1 }); }],
  ['clip order', (bundle) => { (config(bundle).clips as JSON[]).reverse(); }],
  ['member ID collision', (bundle) => { (config(bundle).clips as JSON[]).push({ id: 'placed', track: 'picture', at: 1, hold: 1 }); }],
  ['parent timing basis', (bundle) => { (bundle.parent.config as Record<string, JSON>).output = { fps: 25 }; }],
  ['child timing basis', (bundle) => { config(bundle).output = { fps: 25 }; }],
  ['occurrence extent', (bundle) => { bundle.placements[0].duration_ms = 21000; }],
  ['occurrence origin', (bundle) => { (bundle.placements[0].placement as Record<string, JSON>).start_ms = 9000; }],
  ['expected exclusive owner', (bundle) => { bundle.placements[1].shot_id = bundle.placements[0].shot_id; }],
  ['chosen lane validity', (bundle) => { (config(bundle).tracks as Record<string, JSON>[]).forEach((row) => { row.disabled = true; }); }],
  ['pool absence', (bundle) => { config(bundle).app = { astrid: { pool: ['reserved-new'] } }; }],
  ['migration eligibility', (bundle) => { (bundle.parent.config as Record<string, JSON>).pinnedShotGroups = [{ shotId: 'legacy' }]; }],
  ['reserved registry identity', (bundle) => { ((config(bundle).registry as Record<string, JSON>).assets as Record<string, JSON>)['reserved-new'] = { media_id: 'changed' }; }],
];

for (const golden of allModes) {
  for (const [label, change] of changes) {
    it(`${golden.name} preserves original guards when ${label} changes`, () => {
      const { bundle, basis, media, verified } = input(golden);
      const captured = finishAutoCapture(basis, media, verified);
      const saved = copy(captured.commands[0]);
      change(bundle);
      const head = copy(bundle);
      expect(() => executeAutoBirth(bundle, saved, verified)).toThrow();
      expect(bundle).toEqual(head);
      expect(captured.commands[0]).toEqual(saved);
      expect(finishAutoCapture(basis, media, verified).commands).toEqual(captured.commands);
    });
  }
}

it('guards inherited anchor lane and the shared collision set', () => {
  for (const name of ['shared-video-overlay-anchor', 'shared-image-shift']) {
    const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === name)!);
    const result = finishAutoCapture(basis, media, verified);
    if (name.endsWith('anchor')) child(bundle, 'clip-c').track = 'picture';
    else child(bundle).at = 391 * 1001 / 30000 - 8;
    expect(() => executeAutoBirth(bundle, result.commands[0], verified)).toThrow();
  }
});

it('keeps saved fallback literal while unrelated timing and naming changes rebase', () => {
  const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === 'image-saved')!);
  const captured = finishAutoCapture(basis, media, verified);
  child(bundle).at = 2;
  bundle.parent.name = 'Unrelated';
  const replayed = executeAutoBirth(bundle, captured.commands[0], verified);
  expect(replayed.command).toEqual(captured.commands[0]);
  expect(child(replayed.bundle, 'placed').at).toBe(captured.capture.on - 8);
  expect(captured.capture.start_frame).toBe(667);
  expect(captured.capture.lane).toBe('overlay');
});

it('records missing-anchor membership even for saved fallback', () => {
  const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === 'image-saved')!);
  const result = finishAutoCapture(basis, media, verified);
  (config(bundle).clips as JSON[]).push({ id: 'gone', track: 'picture', at: 2, hold: 1 });
  expect(() => executeAutoBirth(bundle, result.commands[0], verified)).toThrow();
});

it('creates or requires exactly the reserved registry binding without allocating another identity', () => {
  const golden = goldens[0];
  const { bundle, media, verified } = input(golden);
  const assets = (config(bundle).registry as Record<string, JSON>).assets as Record<string, JSON>;
  const binding = { media_id: media.object_id, type: 'image', generationId: media.generation_id, variantId: media.variant_id };
  assets[media.asset] = binding;
  const original = copy(bundle);
  const result = finishAutoCapture(captureAutoBasis(bundle, input(golden).basis.approval), media, verified);
  expect(result.commands[0].created).toEqual([owner + '/clip:placed']);
  expect(assets[media.asset]).toEqual(binding);
  expect(bundle).toEqual(original);
  assets[media.asset] = { ...binding, opaque: true };
  expect(() => finishAutoCapture(captureAutoBasis(bundle, input(golden).basis.approval), media, verified)).toThrow();
});

it('rejects changed exact media tuples, missing fields and metadata substitutions', () => {
  const { basis, media, verified } = input(goldens[0]);
  for (const key of ['asset', 'generation_id', 'variant_id', 'object_id', 'catalog_digest']) {
    const changed = { ...media, [key]: key.endsWith('digest') || key === 'object_id' ? 'sha256:' + 'c'.repeat(64) : 'changed' };
    expect(() => finishAutoCapture(basis, changed, verified)).toThrow();
    const missing = { ...media } as Record<string, unknown>;
    delete missing[key];
    expect(() => finishAutoCapture(basis, missing as MediaSelection, verified)).toThrow();
  }
  expect(() => finishAutoCapture(basis, { ...media, localDuration: 5 } as unknown as MediaSelection, verified)).toThrow();
  expect(() => finishAutoCapture(basis, media, { ...verified, size: 0 })).toThrow();
  expect(() => finishAutoCapture(basis, media, { ...verified, media_type: 'video/mp4' })).toThrow();
});

it('keeps native completion five seconds and shared four seconds instead of full source duration', () => {
  for (const golden of goldens.filter((row) => row.verified.media_type.startsWith('video/'))) {
    const { basis, media, verified } = input(golden);
    const result = finishAutoCapture(basis, media, verified);
    const placed = child(result.bundle, 'placed');
    expect(placed.hold).toBe(golden.approval.mode === 'shared' ? 4 : 5);
    expect(placed.to).toBe(placed.hold);
    expect(() => finishAutoCapture(basis, media, { ...verified, duration_seconds: 3 })).toThrow();
  }
  // Native explicit-duration behavior is separate from the unresolved legacy short-video policy.
  const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === 'completion-video-anchor')!);
  expect(child(finishAutoCapture(captureAutoBasis(bundle, { ...basis.approval, mode: 'completion',
    preferredTrack: null, fallbackAt: null, fallbackTrack: null, duration: 3 }), media, { ...verified, duration_seconds: 3 }).bundle, 'placed').hold).toBe(3);
});

it('requires explicit approval, owner, original lane policy and reserved raw identities', () => {
  const { bundle, basis } = input(goldens[0]);
  for (const patch of [{ autoApprove: false }, { owner: 'parent' }, { ownership: 'shared' }, { clipId: 'display/id' },
    { preferredTrack: undefined }, { fallbackAt: undefined }, { anchor: undefined }]) {
    expect(() => captureAutoBasis(bundle, { ...basis.approval, ...patch } as Parameters<typeof captureAutoBasis>[1])).toThrow();
  }
  expect(() => captureAutoBasis(bundle, { ...basis.approval, owner: 'occurrence:missing' })).toThrow();
});

it('does not turn a changed consumed list or altered recorded guard into an exact retry', () => {
  const { bundle, basis, media, verified } = input(goldens[0]);
  const result = finishAutoCapture(basis, media, verified);
  for (const change of [
    (command: EditCommand) => { command.args.consumed = []; },
    (command: EditCommand) => { command.reads = command.reads!.slice(1); },
    (command: EditCommand) => { command.created = []; },
  ]) {
    const command = copy(result.commands[0]); change(command);
    expect(() => executeAutoBirth(bundle, command, verified)).toThrow();
  }
});

it('leaves pool promotion held for its separate native executor', () => {
  const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === 'shared-image-append')!);
  config(bundle).app = { astrid: { pool: [media.asset] } };
  expect(() => finishAutoCapture(captureAutoBasis(bundle, basis.approval), media, verified)).toThrow('shot.pool');
});

it('preserves raw colon identities and registry aliases that are Object prototype names', () => {
  const { bundle, basis, media, verified } = input(goldens[0]);
  for (const alias of ['reserved:asset', '__proto__', 'constructor']) {
    const pin = { ...media, asset: alias };
    const result = finishAutoCapture(captureAutoBasis(bundle, { ...basis.approval, clipId: 'reserved:child' }), pin, { ...verified, selection: pin });
    expect(child(result.bundle, 'reserved:child').asset).toBe(alias);
    const assets = (config(result.bundle).registry as Record<string, JSON>).assets as Record<string, JSON>;
    expect(Object.hasOwn(assets, alias)).toBe(true);
    expect(new AuthoredState(result.bundle).entity(`${owner}/asset:${alias}`)!.media_id).toBe(media.object_id);
    expect(Object.getPrototypeOf(assets)).toBe(Object.prototype);
    expect(result.commands[0].created).toEqual([`${owner}/asset:${alias}`, `${owner}/clip:reserved:child`]);
  }
});

it('refuses a missing saved lane and does not substitute another lane', () => {
  const { bundle, basis, media, verified } = input(goldens.find((row) => row.name === 'image-preferred')!);
  (config(bundle).tracks as Record<string, JSON>[]) = (config(bundle).tracks as Record<string, JSON>[]).filter((row) => row.id !== 'overlay');
  expect(() => finishAutoCapture(captureAutoBasis(bundle, basis.approval), media, verified)).toThrow('saved placement track');
});

it('keeps the image completion default even with an explicit duration', () => {
  const { bundle, basis, media, verified } = input(goldens[0]);
  const result = finishAutoCapture(captureAutoBasis(bundle, { ...basis.approval, mode: 'completion',
    preferredTrack: null, fallbackAt: null, fallbackTrack: null, duration: 3 }), media, verified);
  expect(child(result.bundle, 'placed').hold).toBe(5);
});
